<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Favoriten – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:950px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.post{border-top:1px solid #e5e9ee;padding:14px 0}.muted{color:#66758a}button{padding:8px 12px;border:0;border-radius:8px;background:#172033;color:#fff;font-weight:700}</style></head><body><main><p><a href="/community">← Community</a></p><h1>Favoriten</h1><section class="card"><?php foreach($posts as $p):?><article class="post"><p><a href="/community/u/<?= rawurlencode($p['username']) ?>"><strong>@<?= $e($p['username']) ?></strong></a><?php if($p['group_name']):?> · <?= $e($p['group_name']) ?><?php endif;?></p><?php if($p['topic']):?><h3><?= $e($p['topic']) ?></h3><?php endif;?><p><?= nl2br($e($p['body'])) ?></p><small class="muted">Gespeichert <?= $e($p['favorited_at']) ?></small><p><a href="/community/posts/<?= rawurlencode($p['id']) ?>">Beitrag öffnen</a></p><form method="post" action="/community/posts/<?= rawurlencode($p['id']) ?>/unfavorite"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="redirect" value="/community/favorites"><button type="submit">Aus Favoriten entfernen</button></form></article><?php endforeach;?><?php if(!$posts):?><p class="muted">Noch keine gespeicherten Beiträge.</p><?php endif;?></section></main></body></html>